import { mkdir, readFile, readdir, rename, rm, stat, writeFile } from 'node:fs/promises'
import { dirname, join, relative, resolve, sep } from 'node:path'
import { randomUUID } from 'node:crypto'
import {
  DeleteObjectCommand,
  GetObjectCommand,
  HeadObjectCommand,
  ListObjectsV2Command,
  NoSuchKey,
  NotFound,
  PutObjectCommand,
  S3Client,
} from '@aws-sdk/client-s3'
import type { Config } from '../config.ts'

/**
 * Minimal object store. Keys are generated by the server only (never from user input)
 * and are validated to rule out path traversal.
 */
export interface Storage {
  put(key: string, body: Buffer, contentType: string): Promise<void>
  get(key: string): Promise<Buffer | null>
  size(key: string): Promise<number | null>
  delete(key: string): Promise<void>
  list(prefix: string): Promise<string[]>
  describe(): string
}

const KEY_PATTERN = /^[a-z0-9][a-z0-9_.-]*(\/[a-z0-9][a-z0-9_.-]*)*$/

export function assertKey(key: string) {
  if (!KEY_PATTERN.test(key) || key.split('/').some((part) => part === '..' || part === '.')) {
    throw new Error(`Ongeldige opslagsleutel: ${key}`)
  }
}

class LocalStorage implements Storage {
  private root: string

  constructor(dataDir: string) {
    this.root = resolve(dataDir)
  }

  private path(key: string) {
    assertKey(key)
    const full = resolve(this.root, ...key.split('/'))
    if (!full.startsWith(this.root + sep)) throw new Error('Pad buiten opslagmap')
    return full
  }

  async put(key: string, body: Buffer) {
    const target = this.path(key)
    await mkdir(dirname(target), { recursive: true })
    // Write to a temporary file first so a crash never leaves a half-written object.
    const tmp = `${target}.${randomUUID()}.tmp`
    await writeFile(tmp, body)
    await rename(tmp, target)
  }

  async get(key: string) {
    try {
      return await readFile(this.path(key))
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null
      throw err
    }
  }

  async size(key: string) {
    try {
      return (await stat(this.path(key))).size
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null
      throw err
    }
  }

  async delete(key: string) {
    await rm(this.path(key), { force: true })
  }

  async list(prefix: string) {
    const dir = resolve(this.root, ...prefix.split('/').filter(Boolean))
    if (dir !== this.root && !dir.startsWith(this.root + sep)) throw new Error('Pad buiten opslagmap')
    try {
      const entries = await readdir(dir, { recursive: true, withFileTypes: true })
      return entries
        .filter((e) => e.isFile() && !e.name.endsWith('.tmp'))
        .map((e) => relative(this.root, join(e.parentPath, e.name)).split(sep).join('/'))
        .sort()
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return []
      throw err
    }
  }

  describe() {
    return `lokale map ${this.root}`
  }
}

class S3Storage implements Storage {
  private client: S3Client
  private bucket: string

  constructor(cfg: Extract<Config['storage'], { driver: 's3' }>) {
    this.bucket = cfg.bucket
    this.client = new S3Client({
      region: cfg.region,
      endpoint: cfg.endpoint,
      forcePathStyle: cfg.forcePathStyle,
      credentials: { accessKeyId: cfg.accessKeyId, secretAccessKey: cfg.secretAccessKey },
    })
  }

  async put(key: string, body: Buffer, contentType: string) {
    assertKey(key)
    await this.client.send(new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: body, ContentType: contentType }))
  }

  async get(key: string) {
    assertKey(key)
    try {
      const res = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }))
      return res.Body ? Buffer.from(await res.Body.transformToByteArray()) : null
    } catch (err) {
      if (err instanceof NoSuchKey || err instanceof NotFound) return null
      throw err
    }
  }

  async size(key: string) {
    assertKey(key)
    try {
      const res = await this.client.send(new HeadObjectCommand({ Bucket: this.bucket, Key: key }))
      return res.ContentLength ?? 0
    } catch (err) {
      if (err instanceof NotFound || (err as { name?: string }).name === 'NotFound') return null
      throw err
    }
  }

  async delete(key: string) {
    assertKey(key)
    await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }))
  }

  async list(prefix: string) {
    const keys: string[] = []
    let token: string | undefined
    do {
      const res = await this.client.send(
        new ListObjectsV2Command({ Bucket: this.bucket, Prefix: prefix, ContinuationToken: token }),
      )
      for (const obj of res.Contents ?? []) if (obj.Key) keys.push(obj.Key)
      token = res.IsTruncated ? res.NextContinuationToken : undefined
    } while (token)
    return keys.sort()
  }

  describe() {
    return `S3-bucket ${this.bucket}`
  }
}

export function createStorage(cfg: Config['storage']): Storage {
  return cfg.driver === 's3' ? new S3Storage(cfg) : new LocalStorage(cfg.dataDir)
}

export async function readJson<T>(storage: Storage, key: string): Promise<T | null> {
  const buf = await storage.get(key)
  return buf ? (JSON.parse(buf.toString('utf8')) as T) : null
}

export async function writeJson(storage: Storage, key: string, value: unknown) {
  await storage.put(key, Buffer.from(JSON.stringify(value, null, 2)), 'application/json')
}
